function piSessionHtml(st) {
  st = st || PI.status || {};
  var a = st.airbnbSession || {};
  var b = st.bookingSession || {};
  function chip(ok, label, when) {
    return '<span style="margin-right:10px">' +
      (ok ? '<span style="color:var(--tx-ok,#059669)">✓</span>' : '<span style="color:var(--tx-err,#b91c1c)">○</span>') +
      ' ' + label +
      (when ? (' <span style="color:var(--tx3);font-size:11px">(' + when + ')</span>') : '') +
      '</span>';
  }
  var needAirbnb = !a.connected;
  return '<div style="font-weight:600;margin-bottom:4px">Portal sessions</div>' +
    '<div>' + chip(!!a.connected, 'Airbnb', a.updatedAt ? String(a.updatedAt).slice(0, 16).replace('T', ' ') : '') +
    chip(!!b.connected, 'Booking.com', b.updatedAt ? String(b.updatedAt).slice(0, 16).replace('T', ' ') : '') + '</div>' +
    (needAirbnb
      ? ('<div style="margin-top:8px;padding:8px 10px;border:1px solid #b91c1c55;border-radius:8px;background:#b91c1c0d;color:var(--tx);font-size:12px;line-height:1.45">' +
         '<b>Airbnb session required.</b> On a laptop with a display:<br>' +
         '<code style="font-size:11px">AIRBNB_HOST_EMAIL=… AIRBNB_HOST_PASSWORD=… node scripts/platform-invoice-save-session.js --channel=airbnb --headed</code><br>' +
         'Complete OTP in the browser → press Enter → copy the printed JSON → click <b>Connect Airbnb</b> and paste → <b>Pull Airbnb</b>.' +
         '</div>')
      : '<div style="margin-top:6px;color:var(--tx3);font-size:11.5px">Airbnb session connected. Pull uses it automatically.</div>');
}
